#include <iostream>

template <typename Derived>
class Comparable
{
public:
    friend bool operator==(const Derived& a, const Derived& b) { return a.compare(b) == 0; }
    friend bool operator<(const Derived& a, const Derived& b) { return a.compare(b) < 0; }
    // TODO: the other four
};

// TODO: Printable<Derived> and Counted<Derived>

class Version : public Comparable<Version>
{
public:
    Version(int major, int minor) : m_major{ major }, m_minor{ minor } {}
    int compare(const Version& other) const
    {
        if (m_major != other.m_major) return m_major < other.m_major ? -1 : 1;
        if (m_minor != other.m_minor) return m_minor < other.m_minor ? -1 : 1;
        return 0;
    }

private:
    int m_major{};
    int m_minor{};
};

int main()
{
    std::cout << std::boolalpha << (Version{ 1, 2 } < Version{ 1, 10 }) << '\n';
    return 0;
}
